CREATE TABLE `FollowUp` (`id` VARCHAR(191) NOT NULL,`patientId` VARCHAR(191) NOT NULL,`practitionerId` VARCHAR(191) NOT NULL,`scheduledAt` DATETIME(3) NOT NULL,`status` ENUM('SCHEDULED','IN_PROGRESS','COMPLETED','CANCELLED') NOT NULL DEFAULT 'SCHEDULED',`summary` TEXT NULL,`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`updatedAt` DATETIME(3) NOT NULL,INDEX `FollowUp_patientId_scheduledAt_idx`(`patientId`,`scheduledAt`),INDEX `FollowUp_practitionerId_status_scheduledAt_idx`(`practitionerId`,`status`,`scheduledAt`),PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `Notification` (`id` VARCHAR(191) NOT NULL,`userId` VARCHAR(191) NOT NULL,`title` VARCHAR(120) NOT NULL,`content` VARCHAR(500) NOT NULL,`readAt` DATETIME(3) NULL,`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),INDEX `Notification_userId_readAt_createdAt_idx`(`userId`,`readAt`,`createdAt`),PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
ALTER TABLE `FollowUp` ADD CONSTRAINT `FollowUp_patientId_fkey` FOREIGN KEY (`patientId`) REFERENCES `User`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE `FollowUp` ADD CONSTRAINT `FollowUp_practitionerId_fkey` FOREIGN KEY (`practitionerId`) REFERENCES `User`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE `Notification` ADD CONSTRAINT `Notification_userId_fkey` FOREIGN KEY (`userId`) REFERENCES `User`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;
